CREATE TABLE projects(root TEXT PRIMARY KEY, config TEXT NOT NULL DEFAULT '{}', touched INTEGER NOT NULL);
CREATE TABLE settings(id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES projects(root), prompt TEXT NOT NULL,status TEXT NOT NULL,model TEXT NOT NULL DEFAULT '',plan TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY, task TEXT NOT NULL REFERENCES tasks(id), kind TEXT NOT NULL, body TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE actions(id TEXT PRIMARY KEY,task TEXT NOT NULL REFERENCES tasks(id),step TEXT NOT NULL,kind TEXT NOT NULL,args TEXT NOT NULL,status TEXT NOT NULL,result TEXT NOT NULL DEFAULT '',beforeText TEXT,afterText TEXT,pid INTEGER,fingerprint TEXT NOT NULL,UNIQUE(task,step));
CREATE TABLE usage(id INTEGER PRIMARY KEY,root TEXT NOT NULL,model TEXT NOT NULL,input INTEGER,output INTEGER,cost REAL,at INTEGER NOT NULL);
CREATE TABLE cooldowns(scope TEXT PRIMARY KEY,untilMs INTEGER NOT NULL,reason TEXT NOT NULL);
PRAGMA user_version=1;
